-- First-pass complete editorial content: Educação Infantil.
-- Basis: DCNEI and Resolução CNE/CEB nº 1/2024.
WITH seed(discipline_name,topic_name,position,title,content) AS (VALUES
('Educação Infantil','Concepções de infância',1,'Conceito central','Infância não é apenas uma etapa biológica; é uma experiência também histórica, social e cultural. A Educação Infantil precisa reconhecer bebês e crianças como sujeitos de direitos, participação, relações e aprendizagem.'),
('Educação Infantil','Concepções de infância',2,'Criança como sujeito','A criança participa ativamente das experiências educativas. Reconhecer sua agência não significa ausência de intencionalidade docente: significa planejar situações em que ela possa explorar, expressar-se e construir sentidos.'),
('Educação Infantil','Concepções de infância',3,'Infâncias diversas','As experiências de infância variam conforme território, condições sociais, cultura, relações familiares e acesso a direitos. Uma prática pedagógica precisa reconhecer essa diversidade sem transformar diferenças em déficit.'),
('Educação Infantil','Concepções de infância',4,'Exemplo para visualizar','Duas crianças podem viver rotinas familiares muito diferentes e participar de maneiras distintas de uma mesma atividade. O planejamento precisa prever múltiplas formas de acolhimento e participação.'),
('Educação Infantil','Concepções de infância',5,'Situação para analisar','Uma escola define um comportamento infantil como “inadequado” sem investigar idade, contexto, comunicação e necessidades. Analise quais concepções de infância estão por trás desse julgamento.'),
('Educação Infantil','Concepções de infância',6,'Erro comum','Imaginar uma infância universal, igual para todas as crianças, e interpretar diferenças de experiência como problemas individuais.'),
('Educação Infantil','Concepções de infância',7,'Aprofundamento','As diretrizes nacionais de qualidade e equidade de 2024 determinam atenção à gestão, infraestrutura, ambientes educativos, processos pedagógicos e condições promotoras do desenvolvimento e aprendizagem de bebês e crianças. citeturn381514search45turn381514search0'),
('Educação Infantil','Concepções de infância',8,'Aplicação pedagógica','Planeje observando interesses, formas de expressão, vínculos, ritmos e contextos das crianças. Registre evidências em vez de depender de impressões gerais.'),
('Educação Infantil','Concepções de infância',9,'Síntese','Compreender a infância exige considerar direitos, diversidade, participação, relações e desenvolvimento em contextos concretos.'),
('Educação Infantil','Concepções de infância',10,'Para revisar','Explique por que reconhecer a criança como sujeito de direitos muda o planejamento pedagógico.'),
('Educação Infantil','Cuidado e educação',1,'Conceito central','Na Educação Infantil, cuidar e educar são dimensões inseparáveis. Alimentação, higiene, descanso, acolhimento e proteção também fazem parte da experiência educativa.'),
('Educação Infantil','Cuidado e educação',2,'Rotina como experiência educativa','Rotinas organizam tempo e previsibilidade, mas podem ser momentos de aprendizagem, autonomia, linguagem, convivência e cuidado compartilhado.'),
('Educação Infantil','Cuidado e educação',3,'Acolhimento','A adaptação à instituição exige relações de confiança entre criança, profissionais e família. Segurança emocional favorece participação e exploração.'),
('Educação Infantil','Cuidado e educação',4,'Exemplo para visualizar','Durante a alimentação, o adulto pode apoiar autonomia, linguagem, escolhas e convivência, em vez de tratar o momento como interrupção do “conteúdo pedagógico”.'),
('Educação Infantil','Cuidado e educação',5,'Situação para analisar','Uma instituição separa rigidamente cuidados e atividades educativas. Analise o que é perdido quando momentos de rotina deixam de ser reconhecidos como experiências formativas.'),
('Educação Infantil','Cuidado e educação',6,'Erro comum','Tratar cuidado como tarefa menor e educação como o único trabalho pedagógico relevante.'),
('Educação Infantil','Cuidado e educação',7,'Aprofundamento','O MEC orienta que o cuidado seja compreendido como indissociável do processo educativo e que a organização curricular considere a integralidade da experiência infantil. citeturn391584search6'),
('Educação Infantil','Cuidado e educação',8,'Aplicação pedagógica','Ao planejar a rotina, registre o que as crianças podem aprender nas transições, refeições, higiene, descanso, acolhimento e organização dos espaços.'),
('Educação Infantil','Cuidado e educação',9,'Síntese','Cuidar e educar acontecem simultaneamente quando a instituição organiza experiências de proteção, vínculo, autonomia, interação e aprendizagem.'),
('Educação Infantil','Cuidado e educação',10,'Para revisar','Descreva uma rotina de cuidado e explique quais aprendizagens podem acontecer durante ela.'),
('Educação Infantil','Brincadeiras e interações',1,'Conceito central','As interações e a brincadeira são eixos estruturantes das práticas pedagógicas da Educação Infantil. Elas permitem experimentar papéis, linguagens, regras, relações e formas de expressão.'),
('Educação Infantil','Brincadeiras e interações',2,'Brincar não é intervalo','Brincadeira pode ser espontânea ou organizada pelo professor. Em ambos os casos, o ambiente, os materiais e as interações influenciam as possibilidades de experiência.'),
('Educação Infantil','Brincadeiras e interações',3,'Papel do professor','O professor observa, organiza o ambiente, oferece materiais, amplia repertórios e intervém quando necessário, sem controlar todos os sentidos da brincadeira.'),
('Educação Infantil','Brincadeiras e interações',4,'Exemplo para visualizar','Uma área de faz-de-conta pode reunir objetos diversos e permitir que as crianças criem enredos, negociem papéis e usem linguagem oral, corporal e simbólica.'),
('Educação Infantil','Brincadeiras e interações',5,'Situação para analisar','Uma professora interrompe frequentemente uma brincadeira para explicar “o objetivo correto”. Analise a diferença entre mediação e controle excessivo.'),
('Educação Infantil','Brincadeiras e interações',6,'Erro comum','Usar brincadeiras apenas como recompensa depois de atividades consideradas “sérias”.'),
('Educação Infantil','Brincadeiras e interações',7,'Aprofundamento','As DCNEI orientam práticas com interações e brincadeira como eixos norteadores e indicam experiências sensoriais, expressivas, corporais e de linguagem. citeturn391584search46'),
('Educação Infantil','Brincadeiras e interações',8,'Aplicação pedagógica','Planeje ambientes que permitam diferentes níveis de desafio e observe como as crianças criam regras, resolvem conflitos, usam materiais e constroem significados.'),
('Educação Infantil','Brincadeiras e interações',9,'Síntese','Brincadeira e interação são formas centrais de experiência infantil e precisam ser tratadas como componentes intencionais do currículo.'),
('Educação Infantil','Brincadeiras e interações',10,'Para revisar','Explique duas formas pelas quais o professor pode apoiar uma brincadeira sem controlar seu resultado.'),
('Educação Infantil','Currículo na Educação Infantil',1,'Conceito central','Currículo na Educação Infantil organiza experiências, relações, linguagens, espaços, tempos e aprendizagens. Não se resume a uma lista de conteúdos disciplinares.'),
('Educação Infantil','Currículo na Educação Infantil',2,'Direitos de aprendizagem','A organização curricular considera direitos de aprendizagem e desenvolvimento que favorecem conviver, brincar, participar, explorar, expressar e conhecer-se.'),
('Educação Infantil','Currículo na Educação Infantil',3,'Campos de experiências','Os campos de experiências organizam referências para o trabalho pedagógico sem transformar a Educação Infantil em um conjunto rígido de disciplinas escolares.'),
('Educação Infantil','Currículo na Educação Infantil',4,'Exemplo para visualizar','Uma experiência de plantio pode envolver cuidado, natureza, linguagem, medidas, registros, cooperação e expressão artística, sem precisar fragmentar a situação em várias aulas isoladas.'),
('Educação Infantil','Currículo na Educação Infantil',5,'Situação para analisar','Uma instituição prepara fichas repetitivas de exercícios para todas as crianças. Analise se essa organização corresponde ao sentido de currículo por experiências.'),
('Educação Infantil','Currículo na Educação Infantil',6,'Erro comum','Antecipar formas escolares do Ensino Fundamental e substituir brincadeira e exploração por excesso de exercícios formais.'),
('Educação Infantil','Currículo na Educação Infantil',7,'Aprofundamento','A Resolução CNE/CEB nº 1/2024 estabelece diretrizes de qualidade e equidade que articulam gestão, infraestrutura, ambientes, processos pedagógicos, desenvolvimento profissional e acompanhamento das aprendizagens. citeturn381514search45'),
('Educação Infantil','Currículo na Educação Infantil',8,'Aplicação pedagógica','Construa propostas a partir de experiências significativas, definindo intencionalidades sem retirar das crianças possibilidades de exploração e participação.'),
('Educação Infantil','Currículo na Educação Infantil',9,'Síntese','Currículo da Educação Infantil é organização intencional de experiências e relações voltadas ao desenvolvimento integral e à aprendizagem das crianças.'),
('Educação Infantil','Currículo na Educação Infantil',10,'Para revisar','Explique por que currículo da Educação Infantil não deve ser confundido com uma lista de matérias.'),
('Educação Infantil','Avaliação e documentação pedagógica',1,'Conceito central','Avaliar na Educação Infantil significa acompanhar processos de aprendizagem e desenvolvimento por meio de observação, registros, documentação e análise pedagógica, sem reduzir a criança a notas.'),
('Educação Infantil','Avaliação e documentação pedagógica',2,'Observação intencional','Observar pedagogicamente exige foco: o professor define o que acompanhar, registra evidências e retoma os registros para planejar novas experiências.'),
('Educação Infantil','Avaliação e documentação pedagógica',3,'Documentação','Fotos, falas, produções, registros escritos e outros materiais podem compor documentação pedagógica quando utilizados para tornar processos visíveis e apoiar interpretação.'),
('Educação Infantil','Avaliação e documentação pedagógica',4,'Exemplo para visualizar','Ao acompanhar uma criança em uma sequência de desenho, o professor registra mudanças nas estratégias, linguagem e representação ao longo das experiências, em vez de atribuir uma nota final.'),
('Educação Infantil','Avaliação e documentação pedagógica',5,'Situação para analisar','Uma instituição compara crianças por meio de classificações rígidas. Analise por que esse procedimento pode ocultar percursos individuais de desenvolvimento e aprendizagem.'),
('Educação Infantil','Avaliação e documentação pedagógica',6,'Erro comum','Confundir documentação pedagógica com arquivo burocrático sem interpretação ou uso para replanejamento.'),
('Educação Infantil','Avaliação e documentação pedagógica',7,'Aprofundamento','As diretrizes de qualidade de 2024 incluem acompanhamento permanente das aprendizagens e do desenvolvimento, orientado pelos marcos curriculares e articulado à qualidade e equidade da oferta. citeturn381514search47'),
('Educação Infantil','Avaliação e documentação pedagógica',8,'Aplicação pedagógica','Depois de registrar uma evidência, escreva qual hipótese pedagógica ela sugere e qual nova experiência pode ajudar a aprofundá-la.'),
('Educação Infantil','Avaliação e documentação pedagógica',9,'Síntese','Avaliação e documentação servem para compreender percursos e orientar o trabalho, e não para classificar crianças como produtos acabados.'),
('Educação Infantil','Avaliação e documentação pedagógica',10,'Para revisar','Qual a diferença entre observar uma criança e realizar uma observação pedagógica?')
)
UPDATE public.material_sections ms
SET title=s.title,content=s.content,section_type=CASE s.position WHEN 1 THEN 'concept' WHEN 2 THEN 'explanation' WHEN 3 THEN 'explanation' WHEN 4 THEN 'examples' WHEN 5 THEN 'examples' WHEN 6 THEN 'common_mistakes' WHEN 7 THEN 'deepening' WHEN 8 THEN 'deepening' WHEN 9 THEN 'review' ELSE 'review' END
FROM seed s,public.materials m,public.topics t,public.disciplines d
WHERE ms.material_id=m.id AND m.topic_id=t.id AND t.discipline_id=d.id
AND d.name=s.discipline_name AND t.name=s.topic_name AND ms.position=s.position AND m.status='draft';